  "bullywug": {"name":"Bullywug","cr":"1/4","xp":50,"size":"Medium","type":"humanoid","alignment":"neutral evil","ac":15,"acNote":"hide armor, shield","hp":11,"hitDice":"2d8+2","speed":"20 ft., swim 40 ft.","abilities":{"str":12,"dex":12,"con":13,"int":7,"wis":10,"cha":7},"saves":{},"skills":{"stealth":3},"resistances":[],"vulnerabilities":[],"immunities":[],"conditionImmunities":[],"senses":"Passive Perception 10","languages":"Bullywug","traits":[{"name":"Amphibious","text":"Can breathe air and water."},{"name":"Speak with Frogs and Toads","text":"Can communicate simple concepts to frogs and toads when it speaks in Bullywug."},{"name":"Swamp Camouflage","text":"Advantage on Dexterity (Stealth) checks made in swampy terrain."},{"name":"Standing Leap","text":"Long jump up to 20 ft. and high jump up to 10 ft., with or without a running start."}],"actions":[{"name":"Multiattack","kind":"multiattack","text":"Makes two attacks: one Bite and one Spear."},{"name":"Bite","kind":"melee","attackBonus":3,"reach":"5 ft.","damage":[{"dice":"1d4+1","type":"bludgeoning"}],"text":""},{"name":"Spear","kind":"melee","attackBonus":3,"reach":"5 ft.","range":"20/60 ft. (thrown)","damage":[{"dice":"1d6+1","type":"piercing"}],"text":"Versatile (1d8) when wielded in two hands."}],"bonusActions":[],"reactions":[],"legendaryActions":[],"spellcasting":null,"sourceBook":"MM 2024"},
  "cambion": {"name":"Cambion","cr":"5","xp":1800,"size":"Medium","type":"Fiend","alignment":"Any Evil","ac":19,"acNote":"scale mail","hp":82,"hitDice":"11d8+33","speed":"30 ft., fly 60 ft.","abilities":{"str":18,"dex":18,"con":16,"int":14,"wis":12,"cha":16},"saves":{"str":7,"dex":7,"int":5,"wis":4},"skills":{"deception":7,"intimidation":7,"perception":4,"stealth":7},"resistances":["cold","fire","lightning","poison","bludgeoning, piercing, and slashing from nonmagical attacks"],"vulnerabilities":[],"immunities":[],"conditionImmunities":[],"senses":"Darkvision 60 ft., Passive Perception 14","languages":"Common, Infernal","traits":[{"name":"Fiendish Blessing","text":"Its AC includes its Charisma bonus (already reflected in AC 19 in 2014 presentation)."}],"actions":[{"name":"Spear","kind":"melee","attackBonus":7,"reach":"5 ft.","damage":[{"dice":"1d6+4","type":"piercing"}],"text":"Melee or ranged (20/60 ft.); 1d8+4 piercing if used with two hands in melee."},{"name":"Fire Ray","kind":"ranged","attackBonus":7,"range":"120 ft.","damage":[{"dice":"3d6","type":"fire"}],"text":"Ranged spell attack."},{"name":"Fiendish Charm","kind":"special","saveAbility":"wis","saveDc":14,"text":"1/day. One humanoid within 30 ft. that it can see makes a Wisdom save or is charmed for 1 day; the charmed target obeys its verbal commands. Ends if target is harmed by the cambion or allies; repeated after long rest failures can cause psychic damage (2014 wording, paraphrased)."}],"bonusActions":[],"reactions":[],"legendaryActions":[],"spellcasting":{"ability":"cha","dc":14,"attackBonus":null,"slots":null,"spells":"At will: alter self, detect magic; 3/day: command; 1/day: plane shift (self only)","text":"Innate spellcasting."},"sourceBook":"MM 2024"},
