  "grimlock": {"name":"Grimlock","cr":"1/4","xp":50,"size":"Medium","type":"humanoid","alignment":"neutral evil","ac":11,"hp":11,"hitDice":"2d8+2","speed":"30 ft.","abilities":{"str":16,"dex":12,"con":12,"int":9,"wis":8,"cha":6},"saves":{},"skills":{"athletics":5,"perception":3,"stealth":3},"resistances":[],"vulnerabilities":[],"immunities":[],"conditionImmunities":[],"senses":"Blindsight 30 ft. (blind beyond this radius), Passive Perception 13","languages":"Undercommon","traits":[{"name":"Blind Senses","text":"Can't use its blindsight while deafened and unable to hear."},{"name":"Keen Hearing","text":"Advantage on Wisdom (Perception) checks that rely on hearing."},{"name":"Stone Camouflage","text":"Advantage on Dexterity (Stealth) checks made in rocky terrain or underground."}],"actions":[{"name":"Stone Club","kind":"melee","attackBonus":5,"reach":"5 ft.","damage":[{"dice":"1d6+3","type":"bludgeoning"},{"dice":"1d6","type":"psychic"}],"text":"The psychic damage applies because the grimlock's attacks channel the alien psychic energy suffusing it."}],"bonusActions":[],"reactions":[],"legendaryActions":[],"spellcasting":null,"sourceBook":"MM 2024"},
