  "thug": {"name":"Tough","cr":"1/2","xp":100,"size":"Medium","type":"Humanoid","alignment":"Any Non-Good Alignment","ac":11,"acNote":"leather armor","hp":32,"hitDice":"5d8+10","speed":30,"abilities":{"str":15,"dex":11,"con":14,"int":10,"wis":10,"cha":11},"saves":{},"skills":{"intimidation":2},"resistances":[],"vulnerabilities":[],"immunities":[],"conditionImmunities":[],"senses":"Passive Perception 10","languages":"Common","traits":[{"name":"Pack Tactics","text":"The tough has advantage on an attack roll against a creature if at least one of the tough's allies is within 5 feet of the target and isn't incapacitated."}],"actions":[{"name":"Multiattack","kind":"multiattack","text":"The tough makes two Mace attacks."},{"name":"Mace","kind":"melee","attackBonus":4,"reach":"5 ft.","damage":[{"dice":"1d6+2","type":"bludgeoning"}],"text":"Enforcer work: knees, knuckles, doors."}],"bonusActions":[],"reactions":[],"legendaryActions":[],"spellcasting":null,"sourceBook":"MM 2024"},
