  "tough boss": {"name":"Tough Boss","cr":"4","xp":1100,"size":"Medium","type":"Humanoid","alignment":"Any Non-Good Alignment","ac":13,"acNote":"leather armor and brawling bulk","hp":85,"hitDice":"10d8+40","speed":30,"abilities":{"str":18,"dex":12,"con":18,"int":10,"wis":11,"cha":13},"saves":{"str":6,"con":6},"skills":{"athletics":6,"intimidation":5},"resistances":[],"vulnerabilities":[],"immunities":[],"conditionImmunities":[],"senses":"Passive Perception 11","languages":"Common","traits":[{"name":"Pack Tactics","text":"The boss has advantage on an attack roll against a creature if at least one of the boss's allies is within 5 feet of the target and isn't incapacitated."},{"name":"Brute","text":"A melee weapon deals one extra die of damage when the boss hits (already included in the attacks)."}],"actions":[{"name":"Multiattack","kind":"multiattack","text":"The boss makes two Maul attacks."},{"name":"Maul","kind":"melee","attackBonus":6,"reach":"5 ft.","damage":[{"dice":"3d6+4","type":"bludgeoning"}],"text":"A dockworker's maul swung with intent; damage includes Brute."}],"bonusActions":[],"reactions":[],"legendaryActions":[],"spellcasting":null,"sourceBook":"MM 2024","provisional":true},
