  "vine blight": {"name":"Vine Blight","cr":"1/2","xp":100,"size":"Medium","type":"plant","alignment":"neutral evil","ac":12,"acNote":"natural armor","hp":26,"hitDice":"4d8+8","speed":"10 ft.","abilities":{"str":15,"dex":8,"con":14,"int":5,"wis":10,"cha":3},"saves":{},"skills":{},"resistances":[],"vulnerabilities":[],"immunities":[],"conditionImmunities":["blinded","deafened"],"senses":"Blindsight 60 ft. (blind beyond this radius), Passive Perception 10","languages":"Understands Common but can't speak","traits":[{"name":"False Appearance","text":"While motionless, indistinguishable from a tangle of vines."}],"actions":[{"name":"Constrict","kind":"melee","attackBonus":4,"reach":"10 ft.","damage":[{"dice":"2d6+2","type":"bludgeoning"}],"text":"The target is grappled (escape DC 12) and restrained until the grapple ends. The blight can constrict only one target this way."},{"name":"Entangling Plants (Recharge 5–6)","kind":"save","saveAbility":"str","saveDc":12,"damage":[],"text":"Grasping roots and vines erupt in a 15-ft. radius centered on the blight for 1 minute. The area is difficult terrain, and each creature in it when the effect appears must succeed on a Strength saving throw or be restrained by the entangling plants. A restrained creature can use an action to make a DC 12 Strength check to free itself."}],"bonusActions":[],"reactions":[],"legendaryActions":[],"spellcasting":null,"sourceBook":"MM 2024"},
  "vrock": {"name":"Vrock","cr":"6","xp":2300,"size":"Large","type":"Fiend (demon)","alignment":"Chaotic Evil","ac":15,"acNote":"natural armor","hp":104,"hitDice":"11d10+44","speed":"40 ft., fly 60 ft.","abilities":{"str":17,"dex":15,"con":18,"int":8,"wis":13,"cha":8},"saves":{"dex":5,"wis":4,"cha":2},"skills":{},"resistances":["cold","fire","lightning","bludgeoning, piercing, and slashing from nonmagical attacks"],"vulnerabilities":[],"immunities":["poison"],"conditionImmunities":["poisoned"],"senses":"Darkvision 120 ft., Passive Perception 11","languages":"Abyssal, telepathy 120 ft.","traits":[{"name":"Magic Resistance","text":"Advantage on saving throws against spells and other magical effects."}],"actions":[{"name":"Multiattack","kind":"multiattack","text":"Makes two attacks: one with its Beak and one with its Talons."},{"name":"Beak","kind":"melee","attackBonus":6,"reach":"5 ft.","damage":[{"dice":"2d6+3","type":"piercing"}],"text":"Melee attack."},{"name":"Talons","kind":"melee","attackBonus":6,"reach":"5 ft.","damage":[{"dice":"2d10+3","type":"slashing"}],"text":"Melee attack."},{"name":"Spores","kind":"save","saveAbility":"con","saveDc":14,"damage":[{"dice":"1d10","type":"poison"}],"text":"Recharge 6. A cloud of toxic spores extends out from the vrock in a 15-foot radius, spreading around corners. Each creature in the area makes a Constitution save or has the Poisoned condition, taking 5 (1d10) poison damage at the start of each of its turns while poisoned this way; it repeats the save at the end of each of its turns, and emptying a vial of holy water on it also ends the effect."},{"name":"Stunning Screech","kind":"save","saveAbility":"con","saveDc":14,"text":"1/Day. Each creature within 20 feet that can hear it and isn't a demon makes a Constitution save or has the Stunned condition until the end of the vrock's next turn."}],"bonusActions":[],"reactions":[],"legendaryActions":[],"spellcasting":null,"sourceBook":"MM 2024"},
