  "warrior commander": {"name":"Warrior Commander","cr":"10","xp":5900,"size":"Medium","type":"Humanoid","alignment":"Any Alignment","ac":19,"acNote":"plate armor","hp":152,"hitDice":"16d8+80","speed":30,"abilities":{"str":19,"dex":12,"con":18,"int":13,"wis":13,"cha":16},"saves":{"str":8,"con":8,"wis":5},"skills":{"athletics":8,"intimidation":7,"perception":5},"resistances":[],"vulnerabilities":[],"immunities":[],"conditionImmunities":[],"senses":"Passive Perception 15","languages":"Common and two other languages","traits":[{"name":"Legendary Resistance (1/Day)","text":"If the commander fails a saving throw, they can choose to succeed instead."},{"name":"Tactical Command","text":"Allies within 30 feet that can hear the commander add 1d4 to their attack rolls while the commander is conscious."}],"actions":[{"name":"Multiattack","kind":"multiattack","text":"The commander makes three Longsword attacks."},{"name":"Longsword","kind":"melee","attackBonus":8,"reach":"5 ft.","damage":[{"dice":"1d8+4","type":"slashing"}],"text":"Two-handed 1d10+4 slashing."},{"name":"Heavy Crossbow","kind":"ranged","attackBonus":5,"range":"100/400 ft.","damage":[{"dice":"1d10+1","type":"piercing"}],"text":"Surveyed from behind the line, fired when it matters."}],"bonusActions":[],"reactions":[{"name":"Parry","text":"When a melee attack would hit the commander, they add 3 to their AC against that attack, possibly turning it into a miss."}],"legendaryActions":[{"name":"Move and Strike","text":"One allied warrior within 60 feet that can hear the commander moves up to its speed and makes one weapon attack."}],"spellcasting":null,"sourceBook":"MM 2024","provisional":true},
