  "white dragon wyrmling": {"name":"White Dragon Wyrmling","cr":"2","xp":450,"size":"Medium","type":"Dragon","alignment":"Chaotic Evil","ac":16,"acNote":"natural armor","hp":32,"hitDice":"5d8+10","speed":"30 ft., burrow 15 ft., fly 60 ft., swim 30 ft.","abilities":{"str":14,"dex":10,"con":14,"int":5,"wis":10,"cha":11},"saves":{"dex":2,"con":4,"cha":3},"skills":{"perception":4,"stealth":2},"resistances":[],"vulnerabilities":[],"immunities":["cold"],"conditionImmunities":[],"senses":"Blindsight 10 ft., darkvision 60 ft., Passive Perception 14","languages":"Draconic","traits":[{"name":"Ice Walk","text":"The dragon can move across icy surfaces without an ability check, and difficult terrain composed of ice or snow doesn't cost extra movement."}],"actions":[{"name":"Bite","kind":"melee","attackBonus":4,"reach":"5 ft.","damage":[{"dice":"1d10+2","type":"piercing"},{"dice":"1d4","type":"cold"}],"text":"Melee attack."},{"name":"Cold Breath (Recharge 5–6)","kind":"save","saveAbility":"con","saveDc":12,"damage":[{"dice":"5d8","type":"cold"}],"text":"Exhales frost in a 15-ft. cone. Constitution save for half damage."}],"bonusActions":[],"reactions":[],"legendaryActions":[],"spellcasting":null,"sourceBook":"MM 2024"},
  "wight": {"name":"Wight","cr":"3","xp":700,"size":"Medium","type":"Undead","alignment":"Neutral Evil","ac":14,"acNote":"studded leather","hp":45,"hitDice":"6d8+18","speed":"30 ft.","abilities":{"str":15,"dex":14,"con":16,"int":10,"wis":13,"cha":15},"saves":{},"skills":{"perception":3,"stealth":4},"resistances":["necrotic","bludgeoning","piercing","slashing"],"vulnerabilities":[],"immunities":["poison"],"conditionImmunities":["exhaustion","poisoned"],"senses":"Darkvision 60 ft., Passive Perception 13","languages":"The languages it knew in life","traits":[{"name":"Sunlight Sensitivity","text":"While in sunlight, disadvantage on attack rolls and on Perception checks that rely on sight."}],"actions":[{"name":"Multiattack","kind":"multiattack","damage":[],"text":"The wight makes two attacks, using Life Drain, Longsword, or Longbow in any combination."},{"name":"Life Drain","kind":"melee","attackBonus":4,"reach":"5 ft.","damage":[{"dice":"1d8+2","type":"necrotic"}],"saveAbility":"con","saveDc":13,"text":"On a hit, the target makes a Constitution save or its HP maximum is reduced by the necrotic damage taken; the reduction lasts until a long rest. A Humanoid slain by this attack rises 24 hours later as a zombie under the wight's control."},{"name":"Longsword","kind":"melee","attackBonus":4,"reach":"5 ft.","damage":[{"dice":"1d8+2","type":"slashing"}],"text":"Melee attack (1d10+2 two-handed)."},{"name":"Longbow","kind":"ranged","attackBonus":4,"range":"150/600 ft.","damage":[{"dice":"1d8+2","type":"piercing"}],"text":"Ranged attack."}],"bonusActions":[],"reactions":[],"legendaryActions":[],"spellcasting":null,"sourceBook":"MM 2024"},
  "will-o'-wisp": {"name":"Will-o'-Wisp","cr":"2","xp":450,"size":"Tiny","type":"Undead","alignment":"Chaotic Evil","ac":19,"hp":22,"hitDice":"9d4","speed":"0 ft., fly 50 ft. (hover)","abilities":{"str":1,"dex":28,"con":10,"int":13,"wis":14,"cha":11},"saves":{},"skills":{},"resistances":["acid","cold","fire","necrotic","thunder","bludgeoning","piercing","slashing"],"vulnerabilities":[],"immunities":["lightning","poison"],"conditionImmunities":["exhaustion","grappled","paralyzed","poisoned","prone","restrained","unconscious"],"senses":"Darkvision 120 ft., Passive Perception 12","languages":"The languages it knew in life","traits":[{"name":"Consume Life","text":"As a Bonus Action, the wisp targets a creature within 5 ft. that has 0 HP. The target makes a DC 10 Constitution save or dies; on a success it is not affected. If the target dies, the wisp regains 10 (3d6) HP."},{"name":"Ephemeral Weapon","text":"A weapon that strikes the wisp passes through it without dealing damage."},{"name":"Incorporeal Movement","text":"The wisp can move through other creatures and objects as if they were difficult terrain; it takes 5 (1d10) force damage if it ends its turn inside an object."},{"name":"Variable Illumination","text":"The wisp sheds bright light in a 5–20 ft. radius and dim light for an additional number of feet equal to the chosen radius; it can alter the radius as a Bonus Action or extinguish/reactivate the light entirely."}],"actions":[{"name":"Shock","kind":"melee","attackBonus":9,"reach":"5 ft.","damage":[{"dice":"2d8","type":"lightning"}],"text":"Melee attack."},{"name":"Invisibility","kind":"other","damage":[],"text":"The wisp and its light magically become Invisible until it attacks, uses Consume Life, or its concentration ends."}],"bonusActions":[],"reactions":[],"legendaryActions":[],"spellcasting":null,"sourceBook":"MM 2024"},
