  "winter wolf": {"name":"Winter Wolf","cr":"3","xp":700,"size":"Large","type":"Monstrosity","alignment":"Neutral Evil","ac":13,"acNote":"natural armor","hp":75,"hitDice":"10d10+20","speed":"50 ft.","abilities":{"str":18,"dex":13,"con":14,"int":7,"wis":12,"cha":8},"saves":{},"skills":{"perception":5,"stealth":3},"resistances":[],"vulnerabilities":[],"immunities":["cold"],"conditionImmunities":[],"senses":"Passive Perception 15","languages":"Common, Giant, Winter Wolf","traits":[{"name":"Keen Hearing and Smell","text":"Advantage on Perception checks that rely on hearing or smell."},{"name":"Pack Tactics","text":"Advantage on attack rolls against a creature if at least one of the wolf's allies is within 5 ft. of the creature and isn't Incapacitated."},{"name":"Snow Camouflage","text":"Advantage on Stealth checks made to hide in snowy terrain."}],"actions":[{"name":"Bite","kind":"melee","attackBonus":6,"reach":"5 ft.","damage":[{"dice":"2d6+4","type":"piercing"}],"saveAbility":"str","saveDc":14,"text":"On a hit, the target makes a Strength save or is knocked Prone."},{"name":"Cold Breath (Recharge 5–6)","kind":"save","saveAbility":"con","saveDc":12,"damage":[{"dice":"4d8","type":"cold"}],"text":"Exhales frigid air in a 15-ft. cone. Constitution save for half damage."}],"bonusActions":[],"reactions":[],"legendaryActions":[],"spellcasting":null,"sourceBook":"MM 2024"},
