  "young white dragon": {"name":"Young White Dragon","cr":"6","xp":2300,"size":"Large","type":"Dragon (chromatic)","alignment":"Chaotic Evil","ac":17,"acNote":"natural armor","hp":133,"hitDice":"14d10+56","speed":"40 ft., burrow 20 ft., fly 80 ft., swim 40 ft.","abilities":{"str":18,"dex":10,"con":18,"int":6,"wis":11,"cha":12},"saves":{"dex":3,"con":7,"wis":3,"cha":4},"skills":{"perception":6,"stealth":3},"resistances":[],"vulnerabilities":[],"immunities":["cold"],"conditionImmunities":[],"senses":"Blindsight 30 ft., darkvision 120 ft., Passive Perception 16","languages":"Common, Draconic","traits":[{"name":"Ice Walk","text":"Can move across and climb icy surfaces without needing an ability check, and difficult terrain composed of ice or snow costs it no extra movement."}],"actions":[{"name":"Multiattack","kind":"multiattack","text":"Makes three Rend attacks."},{"name":"Rend","kind":"melee","attackBonus":7,"reach":"10 ft.","damage":[{"dice":"2d4+4","type":"slashing"},{"dice":"1d4","type":"cold"}],"text":"Melee attack."},{"name":"Cold Breath","kind":"save","saveAbility":"con","saveDc":15,"damage":[{"dice":"9d8","type":"cold"}],"text":"Recharge 5-6. Each creature in a 30-foot cone makes a Constitution save; half damage on a success."}],"bonusActions":[],"reactions":[],"legendaryActions":[],"spellcasting":null,"sourceBook":"MM 2024"},
  "yuan-ti abomination": {"name":"Yuan-ti Abomination","cr":"7","xp":2900,"size":"Large","type":"Monstrosity (shapechanger, yuan-ti)","alignment":"Neutral Evil","ac":15,"acNote":"natural armor","hp":127,"hitDice":"15d10+45","speed":"40 ft.","abilities":{"str":19,"dex":16,"con":17,"int":17,"wis":15,"cha":18},"saves":{},"skills":{"perception":5,"stealth":6},"resistances":[],"vulnerabilities":[],"immunities":["Poison"],"conditionImmunities":["Poisoned"],"senses":"Darkvision 60 ft., Passive Perception 15","languages":"Abyssal, Common, Draconic","traits":[{"name":"Magic Resistance","text":"Advantage on saving throws against spells and other magical effects."}],"actions":[{"name":"Multiattack","kind":"multiattack","damage":[],"text":"Makes two Bite attacks; it can also use Spellcasting to cast Suggestion."},{"name":"Bite","kind":"melee weapon attack","attackBonus":7,"reach":"5 ft.","damage":[{"dice":"2d6+4","type":"Piercing"},{"dice":"3d6","type":"Poison"}],"text":"A venomous bite from its serpent head."},{"name":"Constrict","kind":"special","attackBonus":null,"saveAbility":"Strength","saveDc":15,"damage":[{"dice":"7d6+4","type":"Bludgeoning"}],"text":"Targets a Large or smaller creature within 5 feet. The target makes the save, taking the damage on a failure or half on a success. On a failure it is also Grappled (escape DC 14) and Restrained while Grappled in this way."},{"name":"Poison Spray","kind":"special","attackBonus":null,"saveAbility":"Constitution","saveDc":14,"damage":[{"dice":"6d6","type":"Poison"}],"text":"Recharge 5-6. Sprays poison in a 30-foot Cone. Each creature in the area makes the save, taking half damage on a success. On a failure it takes the damage and is Poisoned until the end of the yuan-ti's next turn, and Blinded while Poisoned in this way."}],"bonusActions":[{"name":"Shape-Shift","text":"Changes into a Large snake or back into its true form. It stays in the chosen form if it dies."}],"reactions":[],"legendaryActions":[],"spellcasting":{"ability":"Wisdom","dc":15,"attackBonus":7,"slots":null,"spells":["Animal Friendship (snakes only)","Suggestion"],"text":"Usable only in yuan-ti form. Casts one of the following spells, requiring no material components. At will: Animal Friendship (snakes only). Three times per day: Suggestion."},"sourceBook":"MM 2024"},
  "yuan-ti malison": {"name":"Yuan-Ti Malison","cr":"3","xp":700,"size":"Medium","type":"Monstrosity","alignment":"Neutral Evil","ac":12,"acNote":"natural armor","hp":51,"hitDice":"6d8+24","speed":"30 ft.","abilities":{"str":16,"dex":14,"con":14,"int":14,"wis":12,"cha":16},"saves":{},"skills":{"deception":5,"stealth":4},"resistances":[],"vulnerabilities":[],"immunities":["poison"],"conditionImmunities":["poisoned"],"senses":"Darkvision 60 ft., Passive Perception 11","languages":"Abyssal, Common, Draconic","traits":[{"name":"Magic Resistance","text":"Advantage on saving throws against spells and other magical effects."},{"name":"Shapechanger","text":"As an action, the malison polymorphs into a snake (one of three forms by type: snake head/humanoid arms, humanoid body/snake head, or snake with a humanoid head), or back into its true form; statistics stay the same except as the form dictates."},{"name":"Innate Spellcasting","text":"The malison casts the following without material components (Charisma, save DC 13): at will — animal friendship (snakes only); 3/day each — suggestion."}],"actions":[{"name":"Multiattack","kind":"multiattack","damage":[],"text":"The malison makes two attacks: one with its Bite (or Constrict, by form) and one with its Scimitar."},{"name":"Bite","kind":"melee","attackBonus":5,"reach":"5 ft.","damage":[{"dice":"1d4+3","type":"piercing"},{"dice":"2d6","type":"poison"}],"text":"Melee attack."},{"name":"Scimitar","kind":"melee","attackBonus":5,"reach":"5 ft.","damage":[{"dice":"1d6+3","type":"slashing"}],"text":"Melee attack."},{"name":"Constrict","kind":"melee","attackBonus":5,"reach":"5 ft.","damage":[{"dice":"2d6+3","type":"bludgeoning"}],"text":"On a hit, a Medium or smaller target is Grappled (escape DC 13) and Restrained until the grapple ends."}],"bonusActions":[],"reactions":[],"legendaryActions":[],"spellcasting":null,"sourceBook":"MM 2024"},
